INSERT INTO craft_projects (id, title_uk, title_en, description_uk, description_en, category, difficulty, estimated_time, photo_url, created_at, updated_at) VALUES
  (1, 'Підвісні кашпо з пластикових пляшок', 'Hanging plastic bottle planters', 'Яскраві підвісні кашпо для зелені й ампельних рослин з пластикових пляшок. Їх можна повісити на паркан, стіну чи балконні перила.', 'Bright hanging planters for herbs and trailing plants made from plastic bottles. Hang them on a fence, a wall or a balcony railing.', 'garden', 'easy', 40, '/images/seed/bottle-planter.jpg', '2026-09-02T10:15:00.000Z', '2026-09-02T10:15:00.000Z'),
  (2, 'Годівничка для птахів з пластикової пляшки', 'Plastic bottle bird feeder', 'Проста годівничка, яку можна зробити разом із дітьми за пів години. Узимку вона допоможе синицям і горобцям.', 'A simple feeder you can make with kids in half an hour. In winter it helps tits and sparrows get through the cold.', 'garden', 'easy', 30, '/images/seed/bottle-bird-feeder.jpg', '2026-08-25T09:00:00.000Z', '2026-08-25T09:00:00.000Z'),
  (3, 'Квіткові горщики з бляшанок', 'Tin can flower pots', 'Бляшанки з-під консервів стають затишними горщиками для квітів і зелені на підвіконні. Потерта фарба додає їм сільського шарму.', 'Food tins become cosy pots for flowers and herbs on a windowsill. Slightly worn paint gives them a rustic charm.', 'garden', 'easy', 45, '/images/seed/tin-can-planters.jpg', '2026-09-14T16:40:00.000Z', '2026-09-14T16:40:00.000Z'),
  (4, 'Лоток для розсади з упаковки від яєць', 'Egg carton seedling tray', 'Картонний лоток для яєць — готова міні-теплиця для розсади. Згодом комірки можна висадити в ґрунт просто разом із рослинами.', 'A cardboard egg carton is a ready-made mini greenhouse for seedlings. Later you can plant each cell straight into the ground together with the seedling.', 'garden', 'easy', 20, '/images/seed/egg-carton-seedlings.jpg', '2026-08-29T12:30:00.000Z', '2026-08-29T12:30:00.000Z'),
  (5, 'Садова клумба зі старих джинсів', 'Garden planter made of old jeans', 'Старі джинси перетворюються на кумедну садову клумбу, яка завжди привертає увагу гостей.', 'Old jeans turn into a quirky garden planter that always catches the eye of your guests.', 'garden', 'medium', 120, '/images/seed/jeans-planter.jpg', '2026-09-21T08:05:00.000Z', '2026-09-21T08:05:00.000Z'),
  (6, 'Свічка в банці з недогарків', 'Jar candle from candle stubs', 'Недогарки старих свічок можна переплавити в нову свічку в скляній банці. Час застигання воску не враховано.', 'Leftover candle stubs can be melted down into a new candle in a glass jar. The time for the wax to set is not included.', 'decor', 'medium', 60, '/images/seed/jar-candle.jpg', '2026-09-08T19:20:00.000Z', '2026-09-08T19:20:00.000Z'),
  (7, 'Підвісні світильники з винних пляшок', 'Wine bottle pendant lights', 'Пляшки з відрізаним дном перетворюються на стильні підвісні світильники для кухні чи тераси. Потрібна обережність зі склом і електрикою.', 'Bottles with the bottoms cut off become stylish pendant lights for a kitchen or a patio. Take care with the glass and the wiring.', 'decor', 'hard', 240, '/images/seed/wine-bottle-lights.jpg', '2026-10-01T11:45:00.000Z', '2026-10-01T11:45:00.000Z'),
  (8, 'Флораріум у скляній банці', 'Glass jar terrarium', 'Міні-сад під склом майже не потребує догляду й чудово прикрашає підвіконня чи робочий стіл.', 'A mini garden under glass needs almost no care and looks great on a windowsill or a desk.', 'decor', 'easy', 40, '/images/seed/jar-terrarium.jpg', '2026-08-27T14:10:00.000Z', '2026-08-27T14:10:00.000Z'),
  (9, 'Музика вітру з винних корків', 'Wine cork wind chime', 'Корки й намистини на дроті тихо постукують на вітрі. Такий підвіс оживить вікно, балкон чи веранду.', 'Corks and beads strung on wire tap softly in the breeze. The chime brings life to a window, a balcony or a porch.', 'decor', 'medium', 90, '/images/seed/cork-wind-chime.jpg', '2026-09-17T13:00:00.000Z', '2026-09-17T13:00:00.000Z'),
  (10, 'Мозаїчне панно з кришечок', 'Bottle cap mosaic panel', 'Велике настінне панно з різнокольорових пластикових кришечок. Кришечки варто збирати заздалегідь, а сам проєкт добре робити всією родиною.', 'A large wall panel made of colourful plastic bottle caps. Start collecting caps in advance; it is a great project for the whole family.', 'decor', 'hard', 300, '/images/seed/bottle-cap-mosaic.jpg', '2026-10-04T15:30:00.000Z', '2026-10-04T15:30:00.000Z'),
  (11, 'Підставки під чашки з винних корків', 'Wine cork coasters', 'Корки, нарізані кружальцями, складаються в міцні підставки під гарячі чашки.', 'Corks sliced into discs make sturdy coasters for hot mugs.', 'household', 'medium', 45, '/images/seed/cork-coasters.jpg', '2026-09-05T17:25:00.000Z', '2026-09-05T17:25:00.000Z'),
  (12, 'Підвісна лампа зі скляної банки', 'Glass jar pendant lamp', 'Банка з металевою кришкою стає світильником у стилі лофт. Кілька таких ламп над столом виглядають особливо ефектно.', 'A jar with a metal lid becomes a loft-style light. Several of them above a table look especially striking.', 'household', 'hard', 120, '/images/seed/jar-pendant-lamp.jpg', '2026-09-25T10:50:00.000Z', '2026-09-25T10:50:00.000Z'),
  (13, 'Плетений килимок зі старих футболок', 'Braided rag rug from old T-shirts', 'Із нарізаних смужками футболок плетуть косу й зшивають її спіраллю — виходить м''який барвистий килимок.', 'T-shirts cut into strips are braided and sewn into a spiral to make a soft, colourful rug.', 'household', 'hard', 360, '/images/seed/rag-rug.jpg', '2026-09-11T09:35:00.000Z', '2026-09-11T09:35:00.000Z'),
  (14, 'Садовий диван з піддонів', 'Pallet garden sofa', 'Зі старих піддонів виходить міцний диван для тераси чи дачі. Це проєкт на цілий день, зате результат прослужить роками.', 'Old pallets make a sturdy sofa for a patio or a country house. It takes a full day, but the result will last for years.', 'household', 'hard', 480, '/images/seed/pallet-sofa.jpg', '2026-10-06T12:00:00.000Z', '2026-10-06T12:00:00.000Z'),
  (15, 'Підставка для олівців з бляшанки', 'Tin can pencil holder', 'Найпростіший органайзер для столу — бляшанка з гладким краєм. Декор — на ваш смак.', 'The simplest desk organiser is a tin can with a smooth rim. Decorate it however you like.', 'storage', 'easy', 20, '/images/seed/tin-can-pencil-holder.jpg', '2026-08-24T08:30:00.000Z', '2026-08-24T08:30:00.000Z'),
  (16, 'Настінна полиця з ящика для фруктів', 'Fruit crate wall shelf', 'Дерев''яний ящик з ринку стає відкритою полицею для книжок, вазонів і дрібниць.', 'A wooden crate from the market becomes an open shelf for books, plants and odds and ends.', 'storage', 'medium', 90, '/images/seed/crate-shelf.jpg', '2026-09-19T18:15:00.000Z', '2026-09-19T18:15:00.000Z'),
  (17, 'Банки для зберігання круп і трав', 'Pantry storage jars', 'Однакові банки з підписами наводять лад на кухонній полиці: одразу видно, що й скільки залишилося.', 'Matching labelled jars bring order to a kitchen shelf: you can see at a glance what is left.', 'storage', 'easy', 30, '/images/seed/pantry-jars.jpg', '2026-09-01T07:45:00.000Z', '2026-09-01T07:45:00.000Z'),
  (18, 'Коробки з кришками для полиці', 'Cardboard shelf boxes with lids', 'З картонних коробок від посилок можна зробити акуратні коробки з кришками для дрібниць на книжковій полиці.', 'Parcel boxes can be turned into neat lidded boxes for odds and ends on a bookshelf.', 'storage', 'medium', 60, '/images/seed/cardboard-storage-boxes.jpg', '2026-09-28T14:55:00.000Z', '2026-09-28T14:55:00.000Z'),
  (19, 'Кораблики з газети', 'Newspaper origami boats', 'Класичний паперовий кораблик складається за 10 хвилин і може плавати в калюжі чи у ванні.', 'The classic paper boat takes 10 minutes to fold and can sail in a puddle or the bath.', 'toys', 'easy', 10, '/images/seed/newspaper-boats.jpg', '2026-08-31T16:20:00.000Z', '2026-08-31T16:20:00.000Z'),
  (20, 'Фігурки-тваринки з втулок', 'Toilet roll animal figures', 'Розфарбовані втулки від туалетного паперу перетворюються на сов, котиків і зайчиків для гри та лялькового театру.', 'Painted toilet paper rolls turn into owls, cats and bunnies for play and puppet shows.', 'toys', 'easy', 30, '/images/seed/toilet-roll-figures.jpg', '2026-09-10T11:05:00.000Z', '2026-09-10T11:05:00.000Z'),
  (21, 'Машинка з картонної коробки', 'Cardboard box toy car', 'Велика коробка стає машинкою, яку дитина може катати й прикрашати. Збирати її разом — половина задоволення.', 'A big box becomes a toy car that a child can push around and decorate. Building it together is half the fun.', 'toys', 'medium', 120, '/images/seed/cardboard-box-car.jpg', '2026-09-23T15:40:00.000Z', '2026-09-23T15:40:00.000Z'),
  (22, 'Ляльковий будиночок з картону', 'Cardboard dollhouse', 'Двоповерховий будиночок із двосхилим дахом з кількох великих коробок. Розфарбовувати його можна разом із дитиною.', 'A two-storey house with a gabled roof built from a few big boxes. Paint it together with your child.', 'toys', 'hard', 300, '/images/seed/cardboard-dollhouse.jpg', '2026-10-03T09:25:00.000Z', '2026-10-03T09:25:00.000Z'),
  (23, 'Резинка-скранчі з клаптика тканини', 'Fabric scrap scrunchie', 'Модна об''ємна резинка для волосся зі шматка тканини, що залишився після шиття чи від старої блузи.', 'A trendy, voluminous hair scrunchie from a piece of leftover fabric or an old blouse.', 'accessories', 'medium', 30, '/images/seed/scrunchie.jpg', '2026-09-06T13:35:00.000Z', '2026-09-06T13:35:00.000Z'),
  (24, 'Клаптева сумка-шопер зі старих джинсів', 'Patchwork denim tote bag', 'Міцна сумка-шопер, зшита з квадратів старих джинсів різних відтінків. Кишені стають зручними відділеннями.', 'A sturdy tote sewn from squares of old jeans in different shades. The pockets become handy compartments.', 'accessories', 'hard', 240, '/images/seed/denim-tote.jpg', '2026-09-30T17:50:00.000Z', '2026-09-30T17:50:00.000Z'),
  (25, 'Брелок-монстрик з клаптиків', 'Fabric scrap monster keychain', 'Маленький м''який брелок з вишитою мордочкою — чудовий спосіб використати найдрібніші клаптики тканини.', 'A small soft keychain with an embroidered face is a great way to use up the tiniest fabric scraps.', 'accessories', 'medium', 60, '/images/seed/fabric-keychain.jpg', '2026-09-15T10:10:00.000Z', '2026-09-15T10:10:00.000Z');
