INSERT INTO craft_project_steps (project_id, step_number, text_uk, text_en) VALUES
  (1, 1, 'Зніміть етикетку й помийте пляшку.', 'Remove the label and wash the bottle.'),
  (1, 2, 'Канцелярським ножем відріжте дно пляшки — це буде верхній отвір кашпо.', 'Cut off the bottom of the bottle with a utility knife — this will be the top opening of the planter.'),
  (1, 3, 'Пробийте цвяхом 2–3 дренажні отвори в кришці.', 'Punch 2–3 drainage holes in the cap with a nail.'),
  (1, 4, 'За бажання пофарбуйте пляшку ззовні акриловою фарбою у два шари й дайте висохнути.', 'If you like, paint the outside of the bottle with two coats of acrylic paint and let it dry.'),
  (1, 5, 'Біля зрізу проколіть два отвори один навпроти одного, протягніть дріт і скрутіть петлю для підвішування.', 'Pierce two opposite holes near the cut edge, thread the wire through and twist it into a hanging loop.'),
  (1, 6, 'Повісьте пляшку горлечком донизу, насипте ґрунт і посадіть розсаду.', 'Hang the bottle neck down, fill it with soil and plant a seedling.'),
  (2, 1, 'Помийте й висушіть пляшку, кришку залиште.', 'Wash and dry the bottle; keep the cap on.'),
  (2, 2, 'Приблизно за 5 см від дна виріжте канцелярським ножем два протилежні віконця розміром близько 6×6 см.', 'About 5 cm above the bottom, cut two opposite windows of about 6×6 cm with a utility knife.'),
  (2, 3, 'Підріжте ножицями гострі краї віконець, щоб птахи не поранилися.', 'Trim the sharp edges of the windows with scissors so the birds do not get hurt.'),
  (2, 4, 'Під горлечком проколіть два отвори, протягніть шпагат і зав''яжіть міцну петлю.', 'Pierce two holes under the neck, pass the twine through and tie a strong loop.'),
  (2, 5, 'Насипте пташиний корм або насіння соняшнику до нижнього краю віконець.', 'Fill with bird seed or sunflower seeds up to the lower edge of the windows.'),
  (2, 6, 'Прив''яжіть годівничку до гілки на висоті щонайменше 1,5 м, щоб її не дістали коти.', 'Tie the feeder to a branch at least 1.5 m above the ground, out of reach of cats.'),
  (3, 1, 'Зніміть етикетки, помийте бляшанки й перевірте, щоб на краю не було гострих задирок.', 'Remove the labels, wash the cans and check that the rims have no sharp burrs.'),
  (3, 2, 'Молотком і цвяхом пробийте в дні кожної бляшанки 3–4 дренажні отвори.', 'Punch 3–4 drainage holes in the bottom of each can with a hammer and nail.'),
  (3, 3, 'За бажання пофарбуйте бляшанки акриловою фарбою й дайте висохнути.', 'If you like, paint the cans with acrylic paint and let them dry.'),
  (3, 4, 'Для вінтажного вигляду злегка потріть наждачним папером фарбу або сам метал.', 'For a vintage look, lightly rub the paint or the bare metal with sandpaper.'),
  (3, 5, 'За бажання обв''яжіть бляшанки шпагатом.', 'If you like, tie twine around the cans.'),
  (3, 6, 'Насипте ґрунт і посадіть квіти чи зелень.', 'Fill with soil and plant flowers or herbs.'),
  (4, 1, 'Відріжте ножицями кришку лотка й підкладіть її під комірки як піддон.', 'Cut the lid off the carton with scissors and put it under the cells as a drip tray.'),
  (4, 2, 'Кінчиком ножиць зробіть невеликий отвір у дні кожної комірки.', 'Make a small hole in the bottom of each cell with the tip of the scissors.'),
  (4, 3, 'Заповніть комірки вологим ґрунтом.', 'Fill the cells with moist soil.'),
  (4, 4, 'Посійте в кожну комірку 1–2 насінини й присипте тонким шаром ґрунту.', 'Sow 1–2 seeds in each cell and cover them with a thin layer of soil.'),
  (4, 5, 'Тримайте лоток у теплому світлому місці й поливайте з пульверизатора.', 'Keep the tray in a warm, bright place and water it with a spray bottle.'),
  (4, 6, 'Коли в розсади з''являться 2–3 справжні листки, розріжте лоток на комірки й висадіть їх у ґрунт.', 'When the seedlings have 2–3 true leaves, cut the cells apart and plant them in the ground.'),
  (5, 1, 'Зашийте низ холош голкою з ниткою.', 'Sew the bottoms of the trouser legs shut with needle and thread.'),
  (5, 2, 'За бажання вставте в холоші дріт як каркас, щоб вони тримали форму.', 'If you like, insert wire into the legs as a frame so they hold their shape.'),
  (5, 3, 'Вистеліть джинси зсередини поліетиленовими пакетами, щоб ґрунт не вимивався крізь тканину.', 'Line the jeans with plastic bags so the soil does not wash out through the fabric.'),
  (5, 4, 'Ножицями зробіть у пакетах унизу кілька дренажних отворів.', 'Snip a few drainage holes in the bags at the bottom with scissors.'),
  (5, 5, 'Посадіть джинси на сходинку чи низький ящик і заповніть ґрунтом до пояса.', 'Seat the jeans on a step or a low box and fill them with soil up to the waist.'),
  (5, 6, 'Висадіть яскраві квіти в «поясі» й добре полийте.', 'Plant bright flowers at the waistband and water them well.'),
  (6, 1, 'Помийте банку й ретельно висушіть.', 'Wash the jar and dry it thoroughly.'),
  (6, 2, 'Розтопіть недогарки на водяній бані в старій каструльці.', 'Melt the candle stubs in an old saucepan over a water bath.'),
  (6, 3, 'Плоскогубцями витягніть з воску старі ґноти й залиште найдовший.', 'Fish the old wicks out of the wax with pliers and keep the longest one.'),
  (6, 4, 'Налийте на дно банки трохи воску й поставте ґніт по центру, притримуючи його плоскогубцями, доки віск не схопиться.', 'Pour a little wax into the jar and set the wick in the centre, holding it with pliers until the wax sets.'),
  (6, 5, 'Залийте решту воску й дайте свічці застигати щонайменше 4 години.', 'Pour in the rest of the wax and let the candle set for at least 4 hours.'),
  (6, 6, 'Підріжте ґніт ножицями до 1 см і за бажання обмотайте шийку банки шпагатом.', 'Trim the wick to 1 cm with scissors and, if you like, wrap twine around the neck of the jar.'),
  (7, 1, 'Замочіть пляшки в теплій воді, зніміть етикетки й висушіть.', 'Soak the bottles in warm water, remove the labels and dry them.'),
  (7, 2, 'Склорізом для пляшок проведіть рівну лінію по колу приблизно за 5 см від дна.', 'Score a line around each bottle with the bottle cutter about 5 cm above the bottom.'),
  (7, 3, 'По черзі поливайте лінію гарячою і холодною водою, доки дно не відокремиться.', 'Pour hot and cold water over the line in turns until the bottom separates.'),
  (7, 4, 'У рукавицях зашліфуйте зріз наждачним папером — спершу крупним, потім дрібним — до гладкості.', 'Wearing gloves, sand the cut edge smooth with sandpaper, first coarse and then fine.'),
  (7, 5, 'Якщо є корок, проріжте канцелярським ножем отвір по його центру — він прикриє горлечко як декоративна заглушка.', 'If you have a cork, cut a hole through its centre with a utility knife; it will cover the neck as a decorative cap.'),
  (7, 6, 'Вимкніть електрику, протягніть кабель крізь горлечко (і корок) та прикрутіть патрон за інструкцією до набору.', 'With the power off, thread the cable through the neck (and the cork) and screw on the socket as the kit instructions say.'),
  (7, 7, 'Підвісьте світильник, вкрутіть світлодіодну лампу й перевірте, щоб скло не торкалося лампи.', 'Hang the light, screw in an LED bulb and check that the glass does not touch the bulb.'),
  (8, 1, 'Помийте велику банку (2–3 л) і добре висушіть.', 'Wash a large jar (2–3 L) and dry it well.'),
  (8, 2, 'Насипте на дно шар камінців або гравію 2–3 см для дренажу.', 'Pour a 2–3 cm layer of pebbles or gravel on the bottom for drainage.'),
  (8, 3, 'Зверху насипте 5–7 см ґрунту.', 'Add 5–7 cm of soil on top.'),
  (8, 4, 'Висадіть невеликі вологолюбні рослини й мох, притискаючи ґрунт навколо.', 'Plant small moisture-loving plants and moss, pressing the soil around them.'),
  (8, 5, 'Підріжте ножицями задовгі листки й сухим пензликом змахніть ґрунт зі скла та листя.', 'Trim long leaves with scissors and brush soil off the glass and leaves with a dry paintbrush.'),
  (8, 6, 'Злегка збризніть водою, закрийте кришку й поставте банку в яскраве розсіяне світло.', 'Mist lightly with water, close the lid and keep the jar in bright, indirect light.'),
  (9, 1, 'Візьміть обрізок палетної дошки завдовжки близько 15 см — це буде основа підвісу.', 'Take a pallet board offcut about 15 cm long as the base of the chime.'),
  (9, 2, 'Просвердліть у дошці 4–5 невеликих отворів для низок і ще два — для петлі.', 'Drill 4–5 small holes in the board for the strands and two more for the hanging loop.'),
  (9, 3, 'Просвердліть уздовж кожного корка тонкий отвір.', 'Drill a thin hole lengthwise through each cork.'),
  (9, 4, 'За бажання розфарбуйте торці корків акриловою фарбою.', 'If you like, paint the ends of the corks with acrylic paint.'),
  (9, 5, 'Нанизуйте корки й намистини по черзі на відрізки дроту, а кінці закріпіть петлями за допомогою плоскогубців.', 'Thread corks and beads alternately onto pieces of wire and secure the ends with loops using pliers.'),
  (9, 6, 'Закріпіть низки під дошкою й зробіть петлю для підвішування зі шпагату або дроту.', 'Fasten the strands under the board and make a hanging loop from twine or wire.'),
  (10, 1, 'Скріпіть палетні дошки поруч двома поперечними планками на шурупах — вийде рівна основа.', 'Join the pallet boards side by side with two cross battens and screws to make a flat backing board.'),
  (10, 2, 'За бажання пофарбуйте основу у фоновий колір і дайте висохнути.', 'If you like, paint the board in a background colour and let it dry.'),
  (10, 3, 'Намалюйте олівцем ескіз на основі, прямі лінії — під лінійку.', 'Sketch the picture on the board in pencil, using a ruler for straight lines.'),
  (10, 4, 'Помийте кришечки й розсортуйте їх за кольорами.', 'Wash the caps and sort them by colour.'),
  (10, 5, 'Приклеюйте кришечки клейовим пістолетом ділянка за ділянкою, починаючи з контуру.', 'Glue the caps on one area at a time with the hot glue gun, starting with the outline.'),
  (10, 6, 'Насамкінець заповніть фон, а ззаду прикрутіть петлю чи гачки для підвішування.', 'Fill in the background last, then screw a hanging loop or hooks onto the back.'),
  (11, 1, 'Гострим канцелярським ножем наріжте корки кружальцями товщиною близько 1 см, звіряючись із лінійкою.', 'Slice the corks into discs about 1 cm thick with a sharp utility knife, checking against a ruler.'),
  (11, 2, 'Викладіть кружальця щільно одне до одного в коло діаметром близько 10 см.', 'Lay the discs out tightly side by side in a circle about 10 cm across.'),
  (11, 3, 'Склейте кружальця між собою клейовим пістолетом.', 'Glue the discs together with the hot glue gun.'),
  (11, 4, 'Якщо маєте клаптик тканини, приклейте знизу тканинне коло, щоб підставка не дряпала стіл.', 'If you have a fabric scrap, glue a fabric circle to the bottom so the coaster does not scratch the table.'),
  (11, 5, 'За бажання обмотайте край двома рядами шпагату й приклейте кінчик.', 'If you like, wrap two rows of twine around the edge and glue the end down.'),
  (12, 1, 'Помийте банку й зніміть етикетку. Знадобиться металева закручувана кришка.', 'Wash the jar and remove the label. You will need a metal screw-on lid.'),
  (12, 2, 'Позначте центр кришки й наметьте його молотком і цвяхом.', 'Mark the centre of the lid and punch a starting dent with a hammer and nail.'),
  (12, 3, 'Просвердліть отвір під діаметр різьби патрона.', 'Drill a hole that matches the diameter of the socket thread.'),
  (12, 4, 'Плоскогубцями загніть усередину гострі задирки навколо отвору.', 'Bend any sharp burrs around the hole inward with pliers.'),
  (12, 5, 'Вимкніть електрику, протягніть кабель крізь кришку, закріпіть патрон кільцевою гайкою й підключіть дроти викруткою за інструкцією до набору.', 'With the power off, pass the cable through the lid, fix the socket with its ring nut and connect the wires with a screwdriver as the kit instructions say.'),
  (12, 6, 'Вкрутіть світлодіодну лампу, накрутіть банку на кришку й підвісьте світильник.', 'Screw in an LED bulb, screw the jar onto the lid and hang the lamp.'),
  (13, 1, 'Відріжте рубці й рукави та наріжте футболки смужками завширшки 3–4 см, вимірюючи лінійкою.', 'Cut off the hems and sleeves and cut the T-shirts into strips 3–4 cm wide, measuring with a ruler.'),
  (13, 2, 'Злегка розтягніть кожну смужку, щоб краї закрутилися в шнур.', 'Stretch each strip a little so the edges curl into a cord.'),
  (13, 3, 'Зшийте три смужки з одного кінця й сплетіть довгу косу, пришиваючи нові смужки в міру плетіння.', 'Sew three strips together at one end and braid a long braid, sewing on new strips as you go.'),
  (13, 4, 'Якщо хочете більше кольорів, додавайте смужки з клаптиків тканини.', 'If you want more colours, mix in strips cut from fabric scraps.'),
  (13, 5, 'Укладайте косу пласкою спіраллю на підлозі, починаючи з центру.', 'Coil the braid into a flat spiral on the floor, starting from the centre.'),
  (13, 6, 'Зшивайте сусідні витки зі зворотного боку міцною ниткою кожні 2–3 см.', 'Sew neighbouring rounds together from the back with strong thread every 2–3 cm.'),
  (13, 7, 'Сховайте кінець коси під останній виток і міцно пришийте.', 'Tuck the end of the braid under the last round and sew it down firmly.'),
  (14, 1, 'Огляньте піддони й закріпіть шурупами розхитані дошки.', 'Inspect the pallets and fasten any loose boards with screws.'),
  (14, 2, 'Ошкурте наждачним папером усі поверхні, яких торкатиметеся, щоб не було скалок.', 'Sand every surface you will touch to get rid of splinters.'),
  (14, 3, 'Покладіть два піддони один на одний для сидіння й скрутіть їх шурупами.', 'Stack two pallets for the seat and screw them together.'),
  (14, 4, 'Поставте ще один піддон вертикально вздовж заднього краю як спинку й закріпіть шурупами через попередньо просвердлені отвори.', 'Stand another pallet upright along the back edge as a backrest and fix it with screws through pre-drilled holes.'),
  (14, 5, 'Повторіть для другої секції, якщо хочете довший або кутовий диван.', 'Repeat for a second section if you want a longer or a corner sofa.'),
  (14, 6, 'За бажання пофарбуйте деревину й дайте висохнути.', 'If you like, paint the wood and let it dry.'),
  (14, 7, 'Покладіть зверху подушки; чохли для них можна пошити з клаптиків тканини.', 'Put cushions on top; their covers can be sewn from fabric scraps.'),
  (15, 1, 'Зніміть етикетку, помийте й висушіть бляшанку.', 'Remove the label, wash the can and dry it.'),
  (15, 2, 'Плоскогубцями загніть усередину гострий край на обідку.', 'Press any sharp edge on the rim inward with pliers.'),
  (15, 3, 'Зашліфуйте обідок наждачним папером, щоб не можна було порізатися.', 'Smooth the rim with sandpaper so nobody can cut themselves.'),
  (15, 4, 'Прикрасьте бляшанку на свій смак: пофарбуйте, пов''яжіть стрічку чи посипте блискітками ще вологу фарбу.', 'Decorate the can as you like: paint it, tie a ribbon around it or sprinkle glitter on the wet paint.'),
  (15, 5, 'Дайте висохнути й поставте в неї олівці та ручки.', 'Let it dry and fill it with pencils and pens.'),
  (16, 1, 'Очистіть ящик і перевірте, чи всі планки міцно тримаються.', 'Clean the crate and check that all the slats are firmly attached.'),
  (16, 2, 'Ошкурте ящик наждачним папером, особливо краї.', 'Sand the crate, especially the edges.'),
  (16, 3, 'За бажання пофарбуйте ящик і дайте висохнути.', 'If you like, paint the crate and let it dry.'),
  (16, 4, 'Просвердліть у задній стінці ящика два отвори й позначте їхнє розташування на стіні.', 'Drill two holes in the back of the crate and mark their positions on the wall.'),
  (16, 5, 'Просвердліть стіну в позначених місцях і прикрутіть ящик шурупами (для бетону чи цегли — з дюбелями).', 'Drill the wall at the marks and screw the crate on (use wall plugs for concrete or brick).'),
  (16, 6, 'Перевірте, чи полиця висить рівно, і наповніть її.', 'Check that the shelf hangs level and fill it.'),
  (17, 1, 'Замочіть банки в гарячій воді й зніміть етикетки та залишки клею.', 'Soak the jars in hot water and remove the labels and glue residue.'),
  (17, 2, 'Ретельно помийте й висушіть банки та кришки.', 'Wash and dry the jars and lids thoroughly.'),
  (17, 3, 'За бажання пофарбуйте кришки в один колір, щоб набір виглядав однаково.', 'If you like, paint the lids the same colour so the set looks uniform.'),
  (17, 4, 'Виріжте ножицями ярлички з паперу й підпишіть уміст.', 'Cut labels out of paper and write the contents on them.'),
  (17, 5, 'Наклейте ярлички або прив''яжіть їх шпагатом до шийки.', 'Stick the labels on or tie them around the necks with twine.'),
  (17, 6, 'Наповніть банки крупами, макаронами чи сушеними травами.', 'Fill the jars with grains, pasta or dried herbs.'),
  (18, 1, 'Виміряйте глибину й висоту полиці та визначте розмір коробки.', 'Measure the depth and height of the shelf and decide on the box size.'),
  (18, 2, 'Канцелярським ножем під лінійку відріжте клапани з верху коробки.', 'Cut the flaps off the top of the box with a utility knife, guided by a ruler.'),
  (18, 3, 'Для кришки виріжте шматок картону, на 1 см більший за коробку з кожного боку, і смужки завширшки 4 см для бортика.', 'For the lid, cut a piece of cardboard 1 cm larger than the box on every side, plus 4 cm wide strips for the rim.'),
  (18, 4, 'Приклейте смужки-бортики по краях кришки.', 'Glue the rim strips along the edges of the lid.'),
  (18, 5, 'Перевірте, чи кришка добре сідає, і дайте клею повністю висохнути.', 'Check that the lid fits well and let the glue dry completely.'),
  (19, 1, 'Виріжте з газетного аркуша прямокутник приблизно 20×30 см.', 'Cut a rectangle of about 20×30 cm from a newspaper page.'),
  (19, 2, 'Складіть його навпіл, а потім загніть верхні кути до середньої лінії, щоб вийшов трикутник.', 'Fold it in half, then fold the top corners down to the centre line to form a triangle.'),
  (19, 3, 'Загніть нижні смужки догори з обох боків — вийде паперовий капелюшок.', 'Fold the bottom strips up on both sides — you now have a paper hat.'),
  (19, 4, 'Розкрийте капелюшок знизу, сплющіть його в квадрат і загніть нижні кути догори з обох боків.', 'Open the hat from the bottom, flatten it into a square and fold the lower corners up on both sides.'),
  (19, 5, 'Знову розкрийте трикутник у квадрат і обережно потягніть верхні кути в сторони — кораблик готовий.', 'Open the triangle into a square again and gently pull the top corners apart — the boat is ready.'),
  (20, 1, 'Пофарбуйте кожну втулку в основний колір і дайте висохнути.', 'Paint each roll in a base colour and let it dry.'),
  (20, 2, 'Загніть верхній край усередину з двох боків — вийдуть вушка.', 'Press the top edge inward from both sides to form ears.'),
  (20, 3, 'Тонким пензликом намалюйте мордочку, животик і лапки.', 'Paint the face, tummy and paws with a thin brush.'),
  (20, 4, 'Приклейте ґудзики-очі, виріжте з клаптиків тканини крильця чи вушка або додайте блискітки — що є під рукою.', 'Glue on buttons as eyes, cut wings or ears from fabric scraps, or add glitter — whatever you have to hand.'),
  (20, 5, 'Дайте всьому висохнути й придумайте тваринкам імена.', 'Let everything dry and give the animals names.'),
  (21, 1, 'Проклейте дно великої коробки, а верхні клапани відріжте.', 'Glue the bottom of the large box shut and cut off the top flaps.'),
  (21, 2, 'Під лінійку розмітьте й виріжте з другої коробки спинку сидіння та лобове скло, а потім вклейте їх клейовим пістолетом.', 'Using a ruler, mark and cut a seat back and a windscreen from the second box, then glue them in with the hot glue gun.'),
  (21, 3, 'Обведіть тарілку на картоні, щоб намалювати чотири колеса, і виріжте їх ножем.', 'Trace around a plate to draw four wheels on cardboard and cut them out with the knife.'),
  (21, 4, 'Склейте кожне колесо з двох шарів картону для міцності й приклейте до боків.', 'Glue each wheel from two layers of cardboard for strength and stick them to the sides.'),
  (21, 5, 'За бажання пофарбуйте машинку й приклейте кришечки як фари та кермо.', 'If you like, paint the car and glue on bottle caps as headlights and a steering wheel.'),
  (21, 6, 'Дайте фарбі й клею висохнути, перш ніж гратися.', 'Let the paint and glue dry before playing.'),
  (22, 1, 'Виберіть найміцнішу коробку для корпусу, відріжте верхні клапани й одну широку стінку — це буде відкритий фасад.', 'Choose the sturdiest box for the body, cut off the top flaps and one wide side to open up the front.'),
  (22, 2, 'Під лінійку виріжте з іншої коробки перекриття й вклейте його посередині висоти.', 'Using a ruler, cut a floor panel from another box and glue it in halfway up.'),
  (22, 3, 'Виріжте дві панелі даху, приклейте їх зверху двосхилом, а гребінь підсильте смужкою картону.', 'Cut two roof panels, glue them on top as a gable and reinforce the ridge with a strip of cardboard.'),
  (22, 4, 'Канцелярським ножем виріжте вікна й двері в бічних стінках.', 'Cut windows and a door in the side walls with the utility knife.'),
  (22, 5, 'Пофарбуйте стіни, підлогу й дах у два шари й дайте висохнути.', 'Paint the walls, floors and roof in two coats and let them dry.'),
  (22, 6, 'Якщо маєте клаптики тканини, зробіть із них килимки й фіранки.', 'If you have fabric scraps, make rugs and curtains from them.'),
  (22, 7, 'Із залишків картону зробіть прості меблі.', 'Make simple furniture from the leftover cardboard.'),
  (23, 1, 'Відміряйте й виріжте смужку тканини 50×10 см.', 'Measure and cut a 50×10 cm strip of fabric.'),
  (23, 2, 'Складіть її навпіл уздовж лицьовим боком досередини й прошийте довгий край.', 'Fold it in half lengthwise, right side in, and sew along the long edge.'),
  (23, 3, 'Виверніть трубку на лицьовий бік.', 'Turn the tube right side out.'),
  (23, 4, 'За допомогою шпильки протягніть крізь трубку 20 см еластичної тасьми й міцно зав''яжіть її кінці.', 'Use a safety pin to thread 20 cm of elastic through the tube and tie its ends together firmly.'),
  (23, 5, 'Вкладіть один кінець трубки в інший і зашийте шов вручну дрібними стібками.', 'Tuck one end of the tube into the other and close the seam by hand with small stitches.'),
  (24, 1, 'Розпоріть або розріжте джинси по швах, зберігши одну-дві задні кишені.', 'Unpick or cut the jeans along the seams, saving one or two back pockets.'),
  (24, 2, 'Під лінійку наріжте квадрати приблизно 12×12 см (плюс 1 см на шви).', 'Using a ruler, cut squares of about 12×12 cm (plus 1 cm seam allowance).'),
  (24, 3, 'Викладіть квадрати, чергуючи світлі й темні відтінки, і зшийте з них дві панелі приблизно 40×40 см.', 'Lay out the squares, alternating light and dark shades, and sew them into two panels of about 40×40 cm.'),
  (24, 4, 'Пришийте кишеню на передню панель.', 'Sew a pocket onto the front panel.'),
  (24, 5, 'Складіть панелі лицьовими боками досередини, зшийте з трьох боків і виверніть сумку.', 'Place the panels right sides together, sew them on three sides and turn the bag right side out.'),
  (24, 6, 'З холош виріжте дві смужки 8×60 см, складіть їх у ручки й міцно пришийте.', 'Cut two 8×60 cm strips from the legs, fold them into straps and sew them on firmly.'),
  (24, 7, 'За бажання вшийте підкладку з тканини й прикрасьте сумку ґудзиками.', 'If you like, sew in a fabric lining and decorate the bag with buttons.'),
  (25, 1, 'Виріжте з клаптиків два однакові прямокутники приблизно 5×7 см.', 'Cut two identical rectangles of about 5×7 cm from fabric scraps.'),
  (25, 2, 'Вишийте мордочку на передній деталі, а якщо маєте ґудзик — пришийте його як око.', 'Embroider a face on the front piece; if you have a button, sew it on as an eye.'),
  (25, 3, 'Сплетіть косичку з трьох відрізків шпагату, нанизуючи намистини, — вийде петля завдовжки близько 10 см.', 'Braid three pieces of twine, threading on beads as you go, to make a loop about 10 cm long.'),
  (25, 4, 'Вкладіть обидва кінці петлі між деталями зверху й обшийте край, залишивши невеликий отвір.', 'Place both ends of the loop between the pieces at the top and sew around the edge, leaving a small gap.'),
  (25, 5, 'Набийте брелок дрібними обрізками тканини й зашийте отвір.', 'Stuff the keychain with small fabric offcuts and sew the gap closed.'),
  (25, 6, 'Злегка розпустіть нижній край на бахрому або пришийте низку намистин.', 'Fray the bottom edge slightly into a fringe or sew on a string of beads.');
